}

repository_context.tests/retry.rs:
use worker::retry::has_retry_budget;

#[test]
fn retry_budget_boundaries() {
    for (completed_attempts, attempt_limit, expected) in [
        (0, 0, false),
        (0, 1, true),
        (1, 1, false),
        (2, 1, false),
        (u32::MAX, u32::MAX, false),
    ] {
        assert_eq!(has_retry_budget(completed_attempts, attempt_limit), expected);
    }
}
